(()=>{'use strict';const form=document.getElementById('siteReviewForm'),list=document.getElementById('siteReviewsList'),notice=document.getElementById('reviewNotice');if(!form)return;
async function load(){try{const response=await fetch('/api/storefront/reviews'),data=await response.json();if(!response.ok)throw Error();list.replaceChildren();for(const review of data.reviews){const card=document.createElement('article'),name=document.createElement('b'),score=document.createElement('span'),text=document.createElement('p');name.textContent=review.author_name;score.textContent=Number(review.rating).toLocaleString('fa-IR')+' از ۵';text.textContent=review.body;card.append(name,score,text);list.append(card);}document.getElementById('reviewSummary').textContent=data.reviews.length?data.reviews.length.toLocaleString('fa-IR')+' نظر تأییدشده':'هنوز نظری تأیید نشده است. نخستین تجربه را شما بنویسید.';}catch{list.textContent='دریافت نظرها انجام نشد؛ دوباره صفحه را باز کنید.';}}
form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;notice.textContent='در حال ارسال…';try{const values=Object.fromEntries(new FormData(form));values.rating=Number(values.rating);const response=await fetch('/api/storefront/reviews',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(values)});if(!response.ok)throw Error(response.status===429?'کمی بعد دوباره تلاش کنید.':'ارسال نظر انجام نشد؛ نام، امتیاز و متن را بررسی کنید.');form.reset();notice.textContent='نظر شما ثبت شد و پس از تأیید مدیر نمایش داده می‌شود.';}catch(error){notice.textContent=error.message;}finally{button.disabled=false;}};load();})();
